import React, { useState, useRef, useEffect, useCallback } from "react";
import { attendanceAPI } from "./api_service";

const CAPTURE_INTERVAL = 900; // stable FPS (~1 FPS safe backend load)
const SUCCESS_PAUSE = 3000;
const MAX_RETRIES = 3;

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const processingRef = useRef(false);

  const [cameraReady, setCameraReady] = useState(false);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  // ================= CAMERA INIT (ROBUST) =================
  const startCamera = async () => {
    try {
      setError(null);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: "user",
          width: { ideal: 1280 },
          height: { ideal: 720 },
        },
        audio: false,
      });

      streamRef.current = stream;

      const video = videoRef.current;
      if (!video) throw new Error("Video not mounted");

      video.srcObject = stream;

      await new Promise((resolve) => {
        video.onloadedmetadata = () => resolve();
      });

      await video.play().catch(() => {
        console.warn("Autoplay blocked retry...");
      });

      setCameraReady(true);
      setAutoMode(true);

      startLoop();

      addNotification?.("📷 Camera ready", "success");
    } catch (err) {
      console.error(err);
      setError("Camera access denied or unavailable");
    }
  };

  // ================= SAFE LOOP =================
  const startLoop = () => {
    if (intervalRef.current) return;

    intervalRef.current = setInterval(async () => {
      if (!autoMode || processingRef.current) return;
      const video = videoRef.current;

      if (!video || video.readyState < 2) return;

      try {
        processingRef.current = true;

        const canvas = canvasRef.current;
        const ctx = canvas.getContext("2d");

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        ctx.drawImage(video, 0, 0);

        const imageBase64 = canvas.toDataURL("image/jpeg", 0.85);

        setFrameCount((f) => f + 1);

        // 🔥 IMPORTANT FIX: JSON FORMAT STRICT BACKEND
        const response = await attendanceAPI.recognize({
          image_base64: imageBase64,
        });

        const data = response?.data;

        if (data?.success && data?.student) {
          setResult({
            success: true,
            name: data.student,
            confidence: (data.confidence * 100).toFixed(1),
            time: new Date().toLocaleTimeString(),
          });

          addNotification?.(`✅ ${data.student}`, "success");

          // anti spam pause
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), SUCCESS_PAUSE);
        }
      } catch (err) {
        console.warn("frame error:", err.message);
      } finally {
        processingRef.current = false;
      }
    }, CAPTURE_INTERVAL);
  };

  // ================= STOP CAMERA CLEAN =================
  const stopCamera = useCallback(() => {
    setAutoMode(false);

    if (intervalRef.current) clearInterval(intervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setCameraReady(false);
  }, []);

  useEffect(() => {
    return () => stopCamera();
  }, [stopCamera]);

  // ================= MANUAL CAPTURE =================
  const manualCapture = async () => {
    if (!videoRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    ctx.drawImage(videoRef.current, 0, 0);

    const imageBase64 = canvas.toDataURL("image/jpeg");

    const response = await attendanceAPI.recognize({
      image_base64: imageBase64,
    });

    setResult(response?.data);
  };

  // ================= UI =================
  return (
    <div style={{ padding: 20 }}>
      <h2>🚀 Ultra Stable Face Recognition</h2>

      <video
        ref={videoRef}
        autoPlay
        muted
        playsInline
        style={{
          width: "100%",
          borderRadius: 12,
          background: "#000",
        }}
      />

      <div style={{ marginTop: 10 }}>
        {!cameraReady ? (
          <button onClick={startCamera}>▶ Start Camera</button>
        ) : (
          <>
            <button onClick={manualCapture}>📸 Scan</button>

            <button onClick={() => setAutoMode(!autoMode)}>
              {autoMode ? "⏸ Pause" : "▶ Resume"}
            </button>

            <button onClick={stopCamera}>🛑 Stop</button>
          </>
        )}
      </div>

      <p>Frames: {frameCount}</p>

      {error && <p style={{ color: "red" }}>{error}</p>}

      {result && (
        <div style={{ marginTop: 20 }}>
          {result.success ? (
            <div>
              ✅ {result.name} ({result.confidence}%)
            </div>
          ) : (
            <div>❌ Not recognized</div>
          )}
        </div>
      )}

      <canvas ref={canvasRef} style={{ display: "none" }} />
    </div>
  );
};

export default CameraRecognition;
